  // BIR setItem45
  setItem45(): any {
  
  	this.d.getElementById("frm1701:txtPg2Pt4I45PersonalExempC1").value = "0";
  	this.d.getElementById("frm1701:txtPg2Pt4I45PersonalExempC2").value = "0";
  
  	if (this.d.getElementById("frm1701:rdoPg1Pt1I7TypeEstate").checked || this.d.getElementById("frm1701:rdoPg1Pt1I7TypeTrust").checked) {
  		
  		this.d.getElementById("frm1701:txtPg2Pt4I45PersonalExempC1").value = "20,000";
  		//Item 16
  		if (this.d.getElementById("frm1701:rdoPg1Pt1I16Joint").checked && this.d.getElementById("frm1701:rdoPg1Pt1I14StatusMarried").checked && this.d.getElementById("frm1701:rdoPg1Pt1I15WithIncome").checked) {
  
  			this.d.getElementById("frm1701:txtPg2Pt4I45PersonalExempC2").value = "20,000";
  		}
  	
  	}else {
  	
  		if (this.d.getElementById("frm1701:rdoPg1Pt1I7TypeSingle").checked || this.d.getElementById("frm1701:rdoPg1Pt1I7TypeProfessional").checked
  			|| this.d.getElementById("frm1701:rdoPg1Pt1I4Compensation").checked
  			|| (this.d.getElementById("frm1701:rdoPg4Pt7I109Compensation").checked && this.d.getElementById("frm1701:rdoPg1Pt1I7TypeSingle").disabled && this.d.getElementById("frm1701:rdoPg1Pt1I7TypeProfessional").disabled)) {
  
  			this.d.getElementById("frm1701:txtPg2Pt4I45PersonalExempC1").value = "50,000";
  			this.d.getElementById("frm1701:txtPg2Pt4I45PersonalExempC2").value = "0";
  		}
  		//Item 16
  		if (this.d.getElementById("frm1701:rdoPg1Pt1I16Joint").checked && this.d.getElementById("frm1701:rdoPg1Pt1I14StatusMarried").checked && this.d.getElementById("frm1701:rdoPg1Pt1I15WithIncome").checked) {
  
  			this.d.getElementById("frm1701:txtPg2Pt4I45PersonalExempC2").value = "50,000";
  		}
  	}
  
  	//trigger Item 45 onblur function
  	this.d.getElementById("frm1701:txtPg2Pt4I45PersonalExempC1").onblur();
  	this.d.getElementById("frm1701:txtPg2Pt4I45PersonalExempC2").onblur();
  }

