  // BIR computeSchedule8A8B
  computeSchedule8A8B(): any {
  
  	this.setValue("0", 'frm1701:txtPg8Sc8AI1GrossIncome,frm1701:txtPg8Sc8AI2TotalDeduction,frm1701:txtPg8Sc8BI1GrossIncome,frm1701:txtPg8Sc8BI2TotalDeductions');
  	var item56A = this.removeCommaParenthesis('frm1701:txtPg2Pt4I56TotalGrossC1');
  	var item57A = this.removeCommaParenthesis('frm1701:txtPg2Pt4I57OrdinaryC1');
  	var item56B = this.removeCommaParenthesis('frm1701:txtPg2Pt4I56TotalGrossC2');
  	var item57B = this.removeCommaParenthesis('frm1701:txtPg2Pt4I57OrdinaryC2');
  
  	if (item56A < item57A) {
  		this.moveValue('frm1701:txtPg2Pt4I56TotalGrossC1', 'frm1701:txtPg8Sc8AI1GrossIncome');
  		this.moveValue('frm1701:txtPg2Pt4I57OrdinaryC1', 'frm1701:txtPg8Sc8AI2TotalDeduction');
  	}
  
  	if (item56B < item57B) {
  		this.moveValue('frm1701:txtPg2Pt4I56TotalGrossC2', 'frm1701:txtPg8Sc8BI1GrossIncome');
  		this.moveValue('frm1701:txtPg2Pt4I57OrdinaryC2', 'frm1701:txtPg8Sc8BI2TotalDeductions');
  	}
  	
  	this.computePg8Sc8A(); this.computePg8Sc8AI4E();
  	this.computePg8Sc8B(); this.computePg8Sc8BI4E();
  }

  // BIR disabledAddMoreLinkSchedule1
