  // BIR disableATCSchedules
  disableATCSchedules(schedules?: any, lastKeyword?: any, isDisable?: any, isReset?: any): any {
  
  	isReset = (typeof (isReset) === "undefined") ? true : isReset;
  	var scheduleArray = schedules.split(',');
  
  	for (var i = 0; i < scheduleArray.length; i++) {
  	
  		this.$("input[id*='" + scheduleArray[i] + "'][id$='" + lastKeyword + "'][name!='frm1701" + "\\:" + "ModalDesc'][name!='frm1701" + "\\:" + "TaxFiler']").attr("disabled", isDisable);
  		
  		if (isReset) {
  		
  			this.$("input[id*='" + scheduleArray[i] + "'][id$='" + lastKeyword + "'][name!='frm1701" + "\\:" + "ModalDesc'][name!='frm1701" + "\\:" + "TaxFiler']").val("");
  			this.$("input[id*='" + scheduleArray[i] + "'][id$='" + lastKeyword + "'][maxlength='12'][name!='frm1701" + "\\:" + "TaxFiler']").val("0");
  		}
  	}
  }

  // BIR addClassName
  addClassName(schedules?: any, lastKeyword?: any, person?: any): any {
  
  	this.isReset = (typeof (this.isReset) === "undefined") ? true : this.isReset;
  	var scheduleArray = schedules.split(',');
  
  	for (var i = 0; i < scheduleArray.length; i++) {
  	
  		if (lastKeyword != '') {
  			this.$("input[id*='" + scheduleArray[i] + "'][id$='" + lastKeyword + "'][name!='frm1701" + "\\:" + "ModalDesc'][name!='frm1701" + "\\:" + "TaxFiler']:disabled").addClass("disabledSchedules");
  		} else {
  			this.$("input[id*='" + scheduleArray[i] + "'][name!='frm1701" + "\\:" + "ModalDesc'][name!='frm1701" + "\\:" + "TaxFiler']:disabled").addClass("disabledSchedules");
  		}
  
  		if (person !== '') {
  			this.$("input[id*='" + scheduleArray[i] + "'][id*='I1" + person + "'][id$='" + lastKeyword + "'][name!='frm1701" + "\\:" + "ModalDesc'][name!='frm1701" + "\\:" + "TaxFiler']:disabled").removeClass("disabledSchedules");
  		}
  		
  		if (scheduleArray[i] == 'Pg8Sc7') {
  			this.$("input[id*='txtPg8Sc7I1" + lastKeyword +"']").removeClass("disabledSchedules");
  		}
  		
  		if (scheduleArray[i] == 'Pg8Sc8A1' || scheduleArray[i] == 'Pg8Sc8B1') {
  			this.$("input[id*='" + scheduleArray[i] + "I5']").removeClass("disabledSchedules");
  		}
  		
  		if(scheduleArray[i] == 'Pg6Sc6' || scheduleArray[i] == 'Pg7Sc6')
  			this.$("input[id*='Pg6Sc6'][id*='I2" + person + "'][id$='" + lastKeyword + "'][name!='frm1701" + "\\:" + "ModalDesc'][name!='frm1701" + "\\:" + "TaxFiler']:disabled").removeClass("disabledSchedules");
  			this.$("input[id*='Pg7Sc6'][id*='I36" + person + "'][id$='" + lastKeyword + "'][name!='frm1701" + "\\:" + "ModalDesc'][name!='frm1701" + "\\:" + "TaxFiler']:disabled").removeClass("disabledSchedules");
  	}
  }

  // BIR confirmCompensationIncome
  confirmCompensationIncome(sender?: any, bool?: any): any {
  
  	if (sender.id == 'frm1701:rdoPg1Pt1I4Compensation') {
  	
  		if (this.isReload == false && bool) {
  			this.alert('For Married Individuals that are Joint Filing, please make sure to accomplish Part VII - Other Relevant Information-SPOUSE. Select Method of Deduction in Part VII.Item 105 and select ATC in Part VII.Item 109 before proceeding to the Schedules');
  		}
  
  		if (this.d.getElementById('frm1701:rdoPg4Pt7I109Compensation').checked && bool) {
  			
  			if (this.confirm("Clicking on 'OK' will remove the selection of Compensation Income on Page 4 Item 109.")) {
  				this.disableATCTaxFiler();
  			}else {
  				this.d.getElementById('frm1701:rdoPg1Pt1I4Compensation').checked = false;
  			}
  		}else {
  			this.disableATCTaxFiler();
  		}
  	
  	}else if (sender.id == 'frm1701:rdoPg4Pt7I109Compensation') {
  		
  		if (this.d.getElementById('frm1701:rdoPg1Pt1I4Compensation').checked && bool) {
  		
  			if (this.confirm("Clicking on 'OK' will remove the selection of Compensation Income on Page 1 Item 4.")) {
  				this.disableATCSpouse();
  			}else {
  				this.d.getElementById('frm1701:rdoPg4Pt7I109Compensation').checked = false;
  			}
  		
  		}else {
  			this.disableATCSpouse();
  		}
  	}
  }

