  // BIR methodOfDeductionsTriggers
  methodOfDeductionsTriggers(person?: any): any {
  
  	//==========================================================================================
  	//03/14/14 Bug #1654
  	//newly added
  	//==========================================================================================
  	var onPage1Taxfiler = (this.d.getElementById('frm1701:txtCurrentPage').value == "1") ? true : false;
  	
  	//[0] :: itemized
  	//[1] :: OSD
  	
  	//Method of Deduction RadioButtons [0]:Itemized [1]:OSD
  	var	MOD = [];
  		MOD = (onPage1Taxfiler) ? this.d.getElementsByName("frm1701:rdoPg1Pt1I20Deduction") : this.d.getElementsByName("frm1701:rdoPg4Pt7I105Itemized")  ;
  	var 	isOSD = (MOD[1].checked) ? true : false
  	
  	var rdoAttachmentEXYES = (onPage1Taxfiler) ? this.d.getElementById('frm1701:rdoPg1Pt1I22IncomeExemptYes').checked : this.d.getElementById('frm1701:rdoPg4Pt7I107Yes').checked;
  	var rdoAttachmentSPYES = (onPage1Taxfiler) ? this.d.getElementById('frm1701:rdoPg1Pt1I23IncomeSpecialYes').checked : this.d.getElementById('frm1701:rdoPg4Pt7I108Yes').checked;
  	
  	if ( isOSD && (rdoAttachmentEXYES || rdoAttachmentSPYES) ){
  	
  		var msgForTaxfiler ="You have selected YES in Part I.Item 22 or 23, Individual taxpayers with mixed income subject to income tax rates are allowed to use only the itemized deductions method. Selecting 'OKAY' will delete existing mandatory attachments";
  		var msgForSpouse = "You have selected YES in Part VII.Item 107 or 108, Individual taxpayers with mixed income subject to income tax rates are allowed to use only the itemized deductions method. Selecting 'OKAY' will delete existing mandatory attachments";
  		var msg = "";
  	
  		msg = (onPage1Taxfiler) ? msgForTaxfiler : msgForSpouse;
  		
  		if (!!this.confirm(msg)) {
  			
  			var rdoEX  = [];
  			var rdoSP = [];
  			
  			//OKAY
  			//DELETE ATTACHMENT
  			if (onPage1Taxfiler){
  				
  				rdoEX = (rdoAttachmentEXYES) ?   this.d.getElementsByName('frm1701:rdoPg1Pt1I22IncomeExempt') : null;
  				rdoSP = (rdoAttachmentSPYES) ?   this.d.getElementsByName('frm1701:rdoPg1Pt1I23IncomeSpecial') : null;
  
  				//uncheck attachment EX
  				if (rdoEX!=null){
  					
  					rdoEX[0].checked = false;
  					rdoEX[1].checked = true;
  				}
  				//uncheck attachment SP
  				if (rdoSP!=null){
  					
  					rdoSP[0].checked = false;
  					rdoSP[1].checked = true;
  				}
  				
  				if (this.totalEXArray.length > 0){
  				this.verifyAddAttachment(-1, this.d.getElementById('frm1701:rdoPg1Pt1I22IncomeExemptNo'), true, 'TAXFILER');
  				}
  				if (this.totalSPArray.length > 0){
  				this.verifyAddAttachment(-1, this.d.getElementById('frm1701:rdoPg1Pt1I23IncomeSpecialNo'), false, 'TAXFILER');
  				}
  				
  			}else{
  				
  				rdoEX = (rdoAttachmentEXYES) ?   this.d.getElementsByName('frm1701:rdoPg4Pt7I107YesNo') : null;
  				rdoSP = (rdoAttachmentSPYES) ?   this.d.getElementsByName('frm1701:rdoPg4Pt7I108YesNo') : null;
  				
  				//uncheck attachment EX
  				if (rdoEX!=null){
  					
  					rdoEX[0].checked = false;
  					rdoEX[1].checked = true;
  				}
  				//uncheck attachment SP
  				if (rdoSP!=null){
  					
  					rdoSP[0].checked = false;
  					rdoSP[1].checked = true;
  				}
  				
  				if (this.totalEXArray.length > 0){
  				this.verifyAddAttachment(-1, this.d.getElementById('frm1701:rdoPg4Pt7I107No'), true, 'SPOUSE');
  				}
  				if (this.totalSPArray.length > 0){
  				this.verifyAddAttachment(-1, this.d.getElementById('frm1701:rdoPg4Pt7I108No'), false, 'SPOUSE');
                  }
  			}
  
  		} else {
  		
  			//uncheck OSD
  			MOD[1].checked = false;
  			//go back to itemized
  			MOD[0].checked = true;
  		}
  	}
  
  //==========================================================================================
  
  if (person.toString() === "Taxfiler") {
          this.isMethodOfDeduction = true;
          this.methodsOfDeductTaxpayerDisabled();
  
          //4/15/2014
          //Add class to Schedules with iterating rows(Sched 3, 5, 6, 8)
          var addClassNameKeyword = 'Pg5Sc3,Pg6Sc5,Pg6Sc6,Pg7Sc6';
          this.addClassName(addClassNameKeyword, 'C1', 'Tax');
          this.addClassName('Pg8Sc7', 'TaxPayer', '');
          this.addClassName('Pg8Sc8A1', '', '');
          this.addClassName(addClassNameKeyword, 'C2', 'Spouse');
          this.addClassName('Pg8Sc7', 'Spouse', '');
          this.addClassName('Pg8Sc8B1', '', '');
  
  		this.disabledFields();
  		this.resetValueOptionalStandardDeduction();
  		
  		this.computePg12Pt9I8('Any');
  		this.summation('Page7Content,Page6Content','TaxSumPayerC1','frm1701:txtPg7Sc6I40TaxTotalPayerC1');
  		this.moveValueToItem57();
  		this.computePg8Sc7('TaxPayer');
  		this.computePg8Sc8A1();
  		this.computePg5Sc4A('TaxPayer');
  		this.computePg6Sc4B('TaxPayer');
  		this.computePg6Sc4C('TaxPayer');
  		this.computePage2Part4('TaxPayer');
  		this.computePage3Part5('TaxPayer');
  		this.computePage1Part2();
  		
  	}else{
          this.isMethodOfDeduction = true;
  		this.methodsOfDeductSpouseDisabled();
  		this.resetValueOptionalStandardDeductionSpouse();
  		
  		this.computePg12Pt9I8('Any');
  		this.summation('Page7Content,Page6Content','SpouseSumC2','frm1701:txtPg7Sc6I40TotalSpouseC2');
  		this.moveValueToItem57();
  		this.computePg8Sc7('Spouse');
  		this.computePg8Sc8B1();
  		this.computePg5Sc4A('Spouse');
  		this.computePg6Sc4B('Spouse');
  		this.computePg6Sc4C('Spouse');
  		this.computePage2Part4('Spouse');
  		this.computePage3Part5('Spouse');
  		this.computePage1Part2();
      }
  
      //4/15/2014
      this.$(".disabledSchedules").attr("disabled", true);
      this.$(".disabledSchedules").removeClass("disabledSchedules");
      this.$(".disableByDefault").attr("disabled", true);
      this.isMethodOfDeduction = false;
  
      //hide page 12
      this.HidePage12Part9();
  }

