  // BIR computeTaxDueRegular
  computeTaxDueRegular(from?: any, to?: any): any {
          var totalTaxableIncome = Math.round(this.removeCommaParenthesis(from));
          var taxDue = 0;
          var taxableIncome = 0;
  
          //Not over 10,000
          if (totalTaxableIncome <= 10000 && totalTaxableIncome >= 0) {
              taxDue = totalTaxableIncome * 0.05;
          }
          //Over 10,000 but not over 30,000
          else if (totalTaxableIncome > 10000 && totalTaxableIncome <= 30000) {
              taxableIncome = totalTaxableIncome - 10000;
              taxDue = (taxableIncome * 0.1) + 500;
          }
          //Over 30,000 but not over 70,000
          else if (totalTaxableIncome > 30000 && totalTaxableIncome <= 70000) {
              taxableIncome = totalTaxableIncome - 30000;
              taxDue = (taxableIncome * 0.15) + 2500;
          }
          //Over 70,000 but not over 140,000
          else if (totalTaxableIncome > 70000 && totalTaxableIncome <= 140000) {
              taxableIncome = totalTaxableIncome - 70000;
              taxDue = (taxableIncome * 0.2) + 8500;
          }
          //Over 140,000 but not over 250,000
          else if (totalTaxableIncome > 140000 && totalTaxableIncome <= 250000) {
              taxableIncome = totalTaxableIncome - 140000;
              taxDue = (taxableIncome * 0.25) + 22500;
          }
          //Over 250,000 but not over 500,000
          else if (totalTaxableIncome > 250000 && totalTaxableIncome <= 500000) {
              taxableIncome = totalTaxableIncome - 250000;
              taxDue = (taxableIncome * 0.3) + 50000;
          }
          //Over 500,000
          else if (totalTaxableIncome > 500000) {
              taxableIncome = totalTaxableIncome - 500000;
              taxDue = (taxableIncome * 0.32) + 125000;
          }
  
          this.d.getElementById(to).value = this.NegativeValue(this.formatCurrencyWOC(Math.round(taxDue)));
      }

  // BIR applicableTaxRatePerTaxTable
  applicableTaxRatePerTaxTable(value?: any): any {
          var totalTaxableIncome = parseFloat(value);
          var taxRate = 0;
  
          //Not over 10,000
          if (totalTaxableIncome > 0 && totalTaxableIncome <= 10000) {
              taxRate = 5;
          }
          //Over 10,000 but not over 30,000
          else if (totalTaxableIncome > 10000 && totalTaxableIncome <= 30000) {
              taxRate = 10;
          }
          //Over 30,000 but not over 70,000
          else if (totalTaxableIncome > 30000 && totalTaxableIncome <= 70000) {
              taxRate = 15;
          }
          //Over 70,000 but not over 140,000
          else if (totalTaxableIncome > 70000 && totalTaxableIncome <= 140000) {
              taxRate = 20;
          }
          //Over 140,000 but not over 250,000
          else if (totalTaxableIncome > 140000 && totalTaxableIncome <= 250000) {
              taxRate = 25;
          }
          //Over 250,000 but not over 500,000
          else if (totalTaxableIncome > 250000 && totalTaxableIncome <= 500000) {
              taxRate = 30;
          }
          //Over 500,000
          else if (totalTaxableIncome > 500000) {
              taxRate = 32;
          }
  
          return taxRate;
      }

  // BIR setToZeroIfEmpty
  setToZeroIfEmpty(e?: any): any {
          var isNumber = false;
  
          if ((e.value.toString().indexOf('(') == -1 || e.value.toString().indexOf(')') == -1) || ((e.id == 'frm1701:txtPg9Sc10I14TaxPayerC1') || (e.id == 'frm1701:txtPg9Sc10I14SpouseC2') || (e.id == 'frm1701:txtPg10Sc11AI1NetIncome') || (e.id == 'frm1701:txtPg10Sc11BI1NetIncome')  || (e.id.indexOf('txtPg5mScKI1NetIncome') > -1)   )){
  	
  		isNumber = this.isNumeric((this.removeCommaParenthesis(e.id)));
          }
  
          if (e.value.toString().trim() === "" || !isNumber) {
              e.value = "0";
          }
          else if ((this.convertToNumber(e.value) < 0) && ((e.id != 'frm1701:txtPg9Sc10I14TaxPayerC1') && (e.id != 'frm1701:txtPg9Sc10I14SpouseC2') && (e.id != 'frm1701:txtPg10Sc11AI1NetIncome') && (e.id != 'frm1701:txtPg10Sc11BI1NetIncome')  && (e.id.indexOf('txtPg5mScKI1NetIncome') <= -1))) {
              e.value = "0";
          }
          else {
              e.value = Math.round((this.removeCommaParenthesis(e.id)));
          }
      }

  // BIR setEmpty
  setEmpty(e?: any): any {
          var isNumber = false;
          if (e.value.toString().indexOf('(') == -1) {
              isNumber = this.isNumeric((this.removeCommaParenthesis(e.id)))
          }
  
          if (e.value.toString().trim() === "" || (!isNumber && this.d.getElementById('frm1701:rdoPg1I34CTC').checked)) {
              e.value = "";
          }
  
          if (e.id == 'frm1701:txtPg4Pt8I116BIRAccreditation' && !isNumber)
              e.value = "";
      }

  // BIR convertToNumber
  convertToNumber(value?: any): any {
          var xNumber = (value) * 1;
  	
          if (xNumber.toString() === "NaN") {
              xNumber = 0;
          }
          return xNumber;
      }

  // BIR convertToFloat
  convertToFloat(value?: any): any {
          var xFloat = (value) * 1;
  	
          if (xFloat.toString() === "NaN") {
              xFloat = 0;
          }
          return xFloat;
      }

  // BIR isNumeric
  isNumeric(num?: any): any {
          return !isNaN(num)
      }

