  // BIR validateTIN
  validateTIN(elem?: any, checkFull?: any): any {
          var isValid = true;
  
          if (elem.value.length < 3 && elem.value !== "" && !checkFull) {
              this.alert("Please provide a valid TIN (must have 3 numbers per box).");
              elem.select();
  
              //isValid = false;
          }
          else if (!!checkFull) {
              var tinArray = this.$_Name(elem.name);
              var totalTIN = 0;
              var tinToFocus = {};
  
              for (var i = (tinArray.length - 1); i >= 0; i--) {
                  totalTIN += tinArray[i].value.length;
                  if (tinArray[i].value.length < 3) {
                      tinToFocus = tinArray[i];
                  }
              }
              if (totalTIN < 12) {
                  //alert("Please provide a valid TIN (must have 3 numbers per box).");
                  //tinToFocus.select();
  
                  isValid = false;
              }
          }
  
          return isValid;
      }

  // BIR computePage123
  computePage123(person?: any): any {
  
  	if (person.toString().trim() === "all"){
  
  		this.computePage2Part4('TaxPayer');
  		this.computePage2Part4('Spouse'); 
  
  		this.computePage3Part5('TaxPayer');
  		this.computePage3Part5('Spouse'); 
  		
  		
  	}else{
  	
  		this.computePage2Part4(person);
  		this.computePage3Part5(person); 
  	}
  	
  	this.computePage1Part2();
  }

