  // BIR computePg6Sc4C
  computePg6Sc4C(person?: any): any {
  	
  		if (person.toString() === "TaxPayer") {
  			
  			this.summation('P6S4CT1', 'Pg6Sc4CI20T,Pg6Sc4CI21T,Pg6Sc4CI22T,Pg6Sc4CI23T,Pg6Sc4CI24T,Pg6Sc4CI25T', 'frm1701:txtPg6Sc4CI26TaxPayerC1');
  
  			var taxPayerI5 = this.convertToFloat(this.removeCommaParenthesis('frm1701:txtPg5Sc4AI5TaxPayerC1'));   
  			var taxPayerI19 = this.convertToFloat(this.removeCommaParenthesis('frm1701:txtPg6Sc4BI19TaxPayerC1')); 
  			var taxPayerI26 = this.convertToFloat(this.removeCommaParenthesis('frm1701:txtPg6Sc4CI26TaxPayerC1'));
  			var taxPayerI27 = this.NegativeValue(this.formatCurrencyWOC(taxPayerI5 + taxPayerI19 + taxPayerI26));
  
  			this.d.getElementById('frm1701:txtPg6Sc4CI27TaxPayerC1').value = taxPayerI27;
  
  			if (this.d.getElementById("frm1701:rdoPg1Pt1I20DeductionOSD").checked == false) {
  				this.moveValue('frm1701:txtPg6Sc4CI27TaxPayerC1', 'frm1701:txtPg2Pt4I53LessCostSalesC1');
  			}
  		}
  		else if (person.toString() === "Spouse") {
  
  			this.summation('P6S4CT1', 'Pg6Sc4CI20S,Pg6Sc4CI21S,Pg6Sc4CI22S,Pg6Sc4CI23S,Pg6Sc4CI24S,Pg6Sc4CI25S', 'frm1701:txtPg6Sc4CI26SpouseC2');
  
  			var spouseI5 = this.convertToFloat(this.removeCommaParenthesis('frm1701:txtPg5Sc4I5SpouseC2'));    
  			var spouseI19 = this.convertToFloat(this.removeCommaParenthesis('frm1701:txtPg6Sc4BI19SpouseC2')); 
  			var spouseI26 = this.convertToFloat(this.removeCommaParenthesis('frm1701:txtPg6Sc4CI26SpouseC2'));
  			var spouseI27 = this.NegativeValue(this.formatCurrencyWOC(spouseI5 + spouseI19 + spouseI26));
  
  			this.d.getElementById('frm1701:txtPg6Sc4CI27SpouseC2').value = spouseI27;
  
  			if (this.d.getElementById("frm1701:rdoPg4Pt7I105OSD").checked == false) {
  				this.moveValue('frm1701:txtPg6Sc4CI27SpouseC2', 'frm1701:txtPg2Pt4I53LessCostSalesC2');
  			}
  		}
  
  		this.computePg12Pt9(person);
  	}

