  // BIR computePage3Part6
  computePage3Part6(person?: any): any {
  
  	    //Item 89 (From Schedule 9 Item 8A/8B)
  
  	    //Item 91 (From Part 9 Item 21B/21F)
  
  	    //Item 92 (From Part 9 Item 21C/21G)
  
  	    if (person.toString() === "TaxPayer") {
  
  	        //Item 86 (sum of Items 66 & 58 * Applicable Tax Rate per Tax Table)
  	        this.summation('Page2Content', 'txtPg2Pt4I66TotalTaxableC1,txtPg2Pt4I58SpecialC1', 'frm1701:txtPg3Pt5I86RegularC1');
  
  	        var taxableIncome = this.convertToFloat(this.removeCommaParenthesis('frm1701:txtPg3Pt5I86RegularC1'));
  	        var taxRate = this.applicableTaxRatePerTaxTable(taxableIncome);
  	        var regularIncomeTaxDue = taxableIncome * this.convertToFloat(taxRate / 100);
  	        //d.getElementById('frm1701:txtPg3Pt5I86RegularC1').value = NegativeValue(formatCurrencyWOC(regularIncomeTaxDue));
  	        this.computeTaxDueRegular('frm1701:txtPg3Pt5I86RegularC1', 'frm1701:txtPg3Pt5I86RegularC1');
  
  	        //Item 87
  	        //computePage2Part4('Taxpayer');
  
  	        //Item 88 (Item 86 Less Item 87)
  	        this.differenceOfElements('frm1701:txtPg3Pt5I86RegularC1', 'frm1701:txtPg3Pt5I87LessTaxC1', 'frm1701:txtPg3Pt5I88TaxRelief1');
  
  	        //Item 90 (Sum of Items 88 & 89)
  	        this.summation('Page3Content', 'Pt5I88TaxRelief1,Pt5I89AddSpecialC1', 'frm1701:txtPg3Pt5I90RegularTaxC1');
  
  	        //Item 93 (Sum of Items 90, 91 & 92)
  	        this.summation('Page3Content', 'Pt5I90RegularTaxC1,Pt5I91SpecialTaxC1,Pt5I92ExemptTaxC1', 'frm1701:txtPg3Pt5I93TotalTaxC1');
  	    }
  	    else if (person.toString() === "Spouse") {
  
  	        //Item 86 (sum of Items 66 & 58 * Applicable Tax Rate per Tax Table)
  	        this.summation('Page2Content', 'txtPg2Pt4I66TotalTaxableC2,txtPg2Pt4I58SpecialC2', 'frm1701:txtPg3Pt5I86RegularC2');
  
  	        var taxableIncome = this.convertToFloat(this.removeCommaParenthesis('frm1701:txtPg3Pt5I86RegularC2'));
  	        var taxRate = this.applicableTaxRatePerTaxTable(taxableIncome);
  	        var regularIncomeTaxDue = taxableIncome * this.convertToFloat(taxRate / 100);
  	        //d.getElementById('frm1701:txtPg3Pt5I86RegularC2').value = NegativeValue(formatCurrencyWOC(regularIncomeTaxDue));
  
  	        this.computeTaxDueRegular('frm1701:txtPg3Pt5I86RegularC2', 'frm1701:txtPg3Pt5I86RegularC2');
  
  	        //Item 87 
  	        //computePage2Part4('Spouse');
  
  	        //Item 88 (Item 86 Less Item 87)
  	        this.differenceOfElements('frm1701:txtPg3Pt5I86RegularC2', 'frm1701:txtPg3Pt5I87LessTaxC2', 'frm1701:txtPg3Pt5I88TaxRelief2');
  
  	        //Item 90 (sum of Items 88 & 89)
  	        this.summation('Page3Content', 'Pt5I88TaxRelief2,Pt5I89AddSpecialC2', 'frm1701:txtPg3Pt5I90RegularTaxC2');
  
  	        //Item 93 (Sum of Items 90, 91 & 92)
  	        this.summation('Page3Content', 'Pt5I90RegularTaxC2,Pt5I91SpecialTaxC2,Pt5I92ExemptTaxC2', 'frm1701:txtPg3Pt5I93TotalTaxC2');
  	    }
  
  	    //Item 94 (Sum of Items 93A & 93B)
  	    this.summation('Page3Content', 'Pt5I93TotalTaxC1,Pt5I93TotalTaxC2', 'frm1701:txtPg3Pt5I94TotalTax');
  
  	}

  // BIR computeCollectedValue
  computeCollectedValue(fromID?: any, toID?: any): any {
  		
  		var id = fromID.toString().split(":");
  		
  		var fromCollection = this.$("input[id*=" + ( id[0]+"\\:"+id[1] ) + "]");
  		
  		var total = 0;
  
  		for (var i = 0; i < fromCollection.length; i++) {
  			
  			//do not compute textbox with id TYPE, they are the source HTML
  			if (fromCollection[i].id.indexOf("TYPE") === -1){
  				
  				total = this.convertToFloat(this.removeCommaParenthesis(fromCollection[i].id )) + total;  
  				//alert(i+ ": " + convertToFloat(fromCollection[i].value)  + "  || id "+fromCollection[i].id);
  			}
  		}
  		this.d.getElementById(toID).value = this.NegativeValue(this.formatCurrencyWOC(Math.round(total)));
  	}

