  	var eTIN3 = this.d.getElementById('frm1701:txtPg5Sc1I'+idGet+'EmpTIN3C1').value;
  	var eTIN4 = this.d.getElementById('frm1701:txtPg5Sc1I'+idGet+'EmpTIN4C1').value;
