  	var eWithheld = this.d.getElementById('frm1701:txtPg5Sc1I'+idGet+'TaxWithheldC3').value;
  
  	var isTaxpayer = this.d.getElementById('frm1701:rdoPg5Sc1I'+idGet+'Taxpayer').checked;
  	var isTaxpayerDisabled = this.d.getElementById('frm1701:rdoPg5Sc1I'+idGet+'Taxpayer').disabled;
  	var isSpouseDisabled = this.d.getElementById('frm1701:rdoPg5Sc1I'+idGet+'Spouse').disabled;
  	
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'NameOfEmp').value = ename;
