  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'EmpTIN2C1').value = eTIN2;
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'EmpTIN3C1').value = eTIN3;
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'EmpTIN4C1').value = eTIN4;
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'ComIncomeC2').value = eIncome;
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'TaxWithheldC3').value = eWithheld;
  	
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'NameOfEmp').disabled =false;
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'EmpTIN1C1').disabled = false;
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'EmpTIN1C1').disabled = false;
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'EmpTIN2C1').disabled = false;
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'EmpTIN3C1').disabled = false;
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'EmpTIN4C1').disabled = false;
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'ComIncomeC2').disabled = false;
  	this.d.getElementById('frm1701:txtPg5Sc1I'+idSet+'TaxWithheldC3').disabled = false;
  
  	this.d.getElementById('frm1701:rdoPg5Sc1I'+idSet+'Taxpayer').checked =  isTaxpayer;
  	this.d.getElementById('frm1701:rdoPg5Sc1I'+idSet+'Spouse').checked  = !isTaxpayer;
  	
  	//copy state on first row
  	this.d.getElementById('frm1701:rdoPg5Sc1I'+idSet+'Taxpayer').disabled =  isTaxpayerDisabled;
  	this.d.getElementById('frm1701:rdoPg5Sc1I'+idSet+'Spouse').disabled  = isSpouseDisabled;
  	
