  // BIR sumTaxSpouseIterate
  sumTaxSpouseIterate(): any {
  
  	var loopCount = (this.d.getElementById('tblGrossCompensationAndTaxWithheldRepository').rows.length) + 5;
  	var totalTaxPayer = 0;
  	var totalSpouse = 0;
  	var totalTaxWithheldTaxPayer = 0;
  	var totalTaxWithheldSpouse = 0;
  
  	var radioArray = new Array;
  	var radioArray1 =  this.d.getElementById("Page5Content").getElementsByTagName("input");
  	var radioArray2 = this.d.getElementById("tblGrossCompensationAndTaxWithheldRepository").getElementsByTagName("input");
  	
  	for (this.a1 = 0; this.a1 < radioArray1.length; this.a1++) {
  		radioArray.push(radioArray1[this.a1]);
  	}
  	for (this.a2 = 0; this.a2 < radioArray2.length; this.a2++) {
  		radioArray.push(radioArray2[this.a2]);
  	}
  
  	for (this.i = 0; this.i < radioArray.length; this.i++) {
  
  		if (radioArray[this.i].type == 'radio') {
  			var radioID = radioArray[this.i].id;
  
  			for (this.a = 1; this.a < loopCount; this.a++) {
  		
  		//item no 4 not included
  		if (this.d.getElementById("tblGrossCompensationAndTaxWithheldRepository").rows.length >= 1) {
  			
  			
  			if (radioID == "frm1701:rdoPg5Sc1I" + [this.a] + "Taxpayer" && "frm1701:txtPg5Sc1I" + [this.a] + "ComIncomeC2" != "frm1701:txtPg5Sc1I4ComIncomeC2") {
  				if (this.d.getElementById("frm1701:rdoPg5Sc1I" + [this.a] + "Taxpayer").checked) {
  				totalTaxPayer += parseInt(this.removeCommaParenthesis("frm1701:txtPg5Sc1I" + [this.a] + "ComIncomeC2"));
  				totalTaxWithheldTaxPayer += parseInt(this.removeCommaParenthesis("frm1701:txtPg5Sc1I" + [this.a] + "TaxWithheldC3"));
  				}
  			}
  
  			if (radioID == "frm1701:rdoPg5Sc1I" + [this.a] + "Spouse" && "frm1701:txtPg5Sc1I" + [this.a] + "TaxWithheldC3" != "frm1701:txtPg5Sc1I4TaxWithheldC3") {
  				if (this.d.getElementById("frm1701:rdoPg5Sc1I" + [this.a] + "Spouse").checked) {
  					totalSpouse += parseInt(this.removeCommaParenthesis("frm1701:txtPg5Sc1I" + [this.a] + "ComIncomeC2"));
  					totalTaxWithheldSpouse += parseInt(this.removeCommaParenthesis("frm1701:txtPg5Sc1I" + [this.a] + "TaxWithheldC3"));
  				}
  			}
  				}
  				else {
  					if (radioID == "frm1701:rdoPg5Sc1I" + [this.a] + "Taxpayer") {
  						if (this.d.getElementById("frm1701:rdoPg5Sc1I" + [this.a] + "Taxpayer").checked) {
  							totalTaxPayer += parseInt(this.removeCommaParenthesis("frm1701:txtPg5Sc1I" + [this.a] + "ComIncomeC2"));
  							totalTaxWithheldTaxPayer += parseInt(this.removeCommaParenthesis("frm1701:txtPg5Sc1I" + [this.a] + "TaxWithheldC3"));
  						}
  					}
  
  					if (radioID == "frm1701:rdoPg5Sc1I" + [this.a] + "Spouse") {
  						if (this.d.getElementById("frm1701:rdoPg5Sc1I" + [this.a] + "Spouse").checked) {
  							totalSpouse += parseInt(this.removeCommaParenthesis("frm1701:txtPg5Sc1I" + [this.a] + "ComIncomeC2"));
  							totalTaxWithheldSpouse += parseInt(this.removeCommaParenthesis("frm1701:txtPg5Sc1I" + [this.a] + "TaxWithheldC3"));
  						}
  					}
  				}
  			}
  		}
     } 
  
  	this.d.getElementById("frm1701:txtPg5Sc1I5ATotalComIncome").value = this.NegativeValue(this.formatCurrencyWOC(totalTaxPayer));
  	this.d.getElementById("frm1701:txtPg5Sc1I5BTotalComIncome").value = this.NegativeValue(this.formatCurrencyWOC(totalSpouse));
  	this.d.getElementById("frm1701:txtPg5Sc1I5ATotalTaxWithheld").value = this.NegativeValue(this.formatCurrencyWOC(totalTaxWithheldTaxPayer));
  	this.d.getElementById("frm1701:txtPg5Sc1I5BTotalTaxWithheld").value = this.NegativeValue(this.formatCurrencyWOC(totalTaxWithheldSpouse));
  
  	this.moveValue('frm1701:txtPg5Sc1I5ATotalTaxWithheld', 'frm1701:txtPg9Sc9I5TaxPayerC1');
  	this.moveValue('frm1701:txtPg5Sc1I5BTotalTaxWithheld', 'frm1701:txtPg9Sc9I5SpouseC2');
  	this.summation('Page9Content', 'Sc9I1Spouse,Sc9I2Spouse,Sc9I3Spouse,Sc9I4Spouse,Sc9I5Spouse,Sc9I6Spouse,Sc9I7Spouse,Sc9I8Spouse,Sc9I9Spouse', 'frm1701:txtPg9Sc9I10SpouseC2');
  	this.summation('Page9Content', 'Sc9I1Tax,Sc9I2Tax,Sc9I3Tax,Sc9I4Tax,Sc9I5Tax,Sc9I6Tax,Sc9I7Tax,Sc9I8Tax,Sc9I9Tax', 'frm1701:txtPg9Sc9I10TaxPayerC1');
  	this.moveValue('frm1701:txtPg9Sc9I10SpouseC2', 'frm1701:txtPg3Pt5I73RegularC2');
  	this.moveValue('frm1701:txtPg9Sc9I10TaxPayerC1', 'frm1701:txtPg3Pt5I73RegularC1');
  	
  	//code from computePg5Sc1I5()
  	this.moveValue('frm1701:txtPg5Sc1I5ATotalComIncome', 'frm1701:txtPg2Pt4I41GrossCompensationC1');
  	this.moveValue('frm1701:txtPg5Sc1I5BTotalComIncome', 'frm1701:txtPg2Pt4I41GrossCompensationC2');
  }

